const fs = require('fs');

function solve() {
    const buffer = fs.readFileSync(0);
    let offset = 0;

    function skipWhitespace() {
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
    }

    function nextBigInt() {
        skipWhitespace();
        if (offset >= buffer.length) return null;
        let sign = 1n;
        if (buffer[offset] === 45) { // '-'
            sign = -1n;
            offset++;
        } else if (buffer[offset] === 43) { // '+'
            offset++;
        }
        let res = 0n;
        while (offset < buffer.length && buffer[offset] >= 48 && buffer[offset] <= 57) {
            res = res * 10n + BigInt(buffer[offset] - 48);
            offset++;
        }
        return res * sign;
    }

    const nBig = nextBigInt();
    if (nBig === null) return;
    const N = Number(nBig);
    const X1 = nextBigInt();
    const X2 = nextBigInt();

    const u = new Array(N);
    const v = new Array(N);

    for (let i = 0; i < N; i++) {
        const A = nextBigInt();
        const B = nextBigInt();
        u[i] = A * X1 + B;
        v[i] = A * X2 + B;
    }

    // Compressão das coordenadas de v
    const vSorted = v.slice().sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
    const uniqueV = [];
    for (let i = 0; i < N; i++) {
        if (i === 0 || vSorted[i] !== vSorted[i - 1]) {
            uniqueV.push(vSorted[i]);
        }
    }

    function getRank(val) {
        let low = 0, high = uniqueV.length - 1;
        while (low <= high) {
            const mid = (low + high) >> 1;
            if (uniqueV[mid] === val) return mid + 1;
            if (uniqueV[mid] < val) low = mid + 1;
            else high = mid - 1;
        }
        return low + 1;
    }

    const rankV = new Int32Array(N);
    for (let i = 0; i < N; i++) {
        rankV[i] = getRank(v[i]);
    }

    // Ordenar os pontos por u
    const indices = new Int32Array(N);
    for (let i = 0; i < N; i++) indices[i] = i;

    indices.sort((i, j) => {
        if (u[i] < u[j]) return -1;
        if (u[i] > u[j]) return 1;
        return 0;
    });

    // Fenwick Tree (BIT)
    const K = uniqueV.length;
    const bit = new Int32Array(K + 1);

    function add(idx, val) {
        for (; idx <= K; idx += idx & -idx) {
            bit[idx] += val;
        }
    }

    function query(idx) {
        let sum = 0;
        for (; idx > 0; idx -= idx & -idx) {
            sum += bit[idx];
        }
        return sum;
    }

    let concordantPairs = 0n;

    // Processar em grupos com o mesmo valor de u
    let i = 0;
    while (i < N) {
        let j = i;
        while (j < N && u[indices[j]] === u[indices[i]]) {
            j++;
        }

        // Consultar para todos do grupo
        for (let k = i; k < j; k++) {
            const r = rankV[indices[k]];
            concordantPairs += BigInt(query(r - 1));
        }

        // Inserir todos do grupo na BIT
        for (let k = i; k < j; k++) {
            const r = rankV[indices[k]];
            add(r, 1);
        }

        i = j;
    }

    const totalPairs = (BigInt(N) * BigInt(N - 1)) / 2n;
    const ans = totalPairs - concordantPairs;

    console.log(ans.toString());
}

solve();
